22	const sum = (amounts: number[]): number =>
23	  amounts.reduce((total, amount) => total + amount, 0);
24	
25	const PROCESSING_FEE = 5;
26	
27	// Binary floating point makes exact multiples land a hair off (100 * 1.1 + 5 =
28	// 115.00000000000001); snap to cent precision so only genuine fractions round up.
29	const roundUpInMHPCOsFavour = (amount: number): number =>
30	  Math.ceil(Number(amount.toFixed(6)));
31	
32	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
33	  sword: 100,
34	  amulet: 60,
35	  staff: 80,
36	  potion: 40,
37	  rune: 25,
38	  moonstone: 25,
39	};
40	
41	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
42	
43	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
44	
45	const COMPONENT_BLOCK_SIZE = 3;
46	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
47	
48	const areAlike = (items: Item[]): boolean =>
49	  items.every((item) => item.type === items[0].type);
50	
51	// Only a whole policy of exactly 3 alike items is priced as a block so far; the
52	// 7-runes and 3-runes-+-3-moonstones tests will force per-type grouping.
53	const policyBasePremiumOf = (items: Item[]): number =>
54	  items.length === COMPONENT_BLOCK_SIZE && areAlike(items)
55	    ? COMPONENT_BLOCK_BASE_PREMIUM
56	    : sum(items.map(basePremiumOf));
57	
58	const quote = (step: QuoteStep): number => {
59	  const policyBasePremium = policyBasePremiumOf(step.items);
60	  const firstInsuranceSurcharge =
61	    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
62	
63	  return roundUpInMHPCOsFavour(
64	    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
65	  );
66	};
67	
68	export const runScenario = (scenario: Scenario): ScenarioResults => {
69	  return { results: scenario.steps.map((step) => ({ premium: quote(step) })) };
70	};
